{
  "summary": "Depomed grants King and its affiliates a co-exclusive right to promote the product. Otherwise, nothing in the contract grants King implicit licenses or rights to Depomed's property.",
  "evidence": [
    {
      "passage_id": 7,
      "quote": "Depomed hereby grants to King and its Affiliates and King and its Affiliates hereby accept a co-exclusive right to Promote the Product under the Depomed Trademarks in the Territory together with Depomed and its Affiliates only, on the terms and subject to the conditions set forth herein."
    },
    {
      "passage_id": 6,
      "quote": "Except as expressly set forth herein, nothing contained herein shall be deemed to grant King, by implication, a license or other right or interest in any patent, trademark or other similar property of Depomed or its Affiliates, except as may be necessary for King to Promote the Product pursuant to this Agreement or to manufacture the Product in accordance with Section 6.6."
    }
  ]
}
